<?php $__env->startSection('content'); ?><div class="page"><div class="eyebrow"></div><h1>Reservasi saya</h1><p class="subtitle mb-4">Pantau jadwal, pesanan menu, dan status pembayaran Anda.</p><?php $__empty_1 = true; $__currentLoopData = $reservasis; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $r): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="panel mb-3"><div class="d-flex justify-content-between flex-wrap gap-2"><div><h5><?php echo e($r->resto->nama); ?></h5><p class="subtitle mb-1"><?php echo e($r->tanggal->format('d M Y')); ?> · <?php echo e(substr($r->jam,0,5)); ?> · <?php echo e($r->jumlah_orang); ?> orang</p><small class="subtitle">Kode booking: <?php echo e($r->id); ?></small></div><div class="text-end"><span class="status status-<?php echo e($r->status); ?>"><?php echo e(str_replace('_',' ',$r->status)); ?></span><div class="small mt-2">DP: <?php echo e($r->status_dp); ?></div></div></div><?php if(in_array($r->status_dp,['belum_bayar','ditolak'])): ?><form class="mt-3 d-flex flex-wrap gap-2 align-items-end" method="POST" enctype="multipart/form-data" action="<?php echo e(route('customer.reservations.proof',$r)); ?>"><?php echo csrf_field(); ?><div><label class="field-label">Unggah bukti transfer DP</label><input class="form-control" type="file" name="bukti_dp" accept="image/*" required></div><button class="btn btn-purple">Kirim bukti DP</button></form><?php elseif($r->bukti_dp): ?><p class="small subtitle mt-3">Bukti DP: <a href="<?php echo e(asset('storage/'.$r->bukti_dp)); ?>" target="_blank" rel="noopener">Lihat file</a></p><?php endif; ?><hr><div class="row"><div class="col-md-7"><strong>Detail menu</strong><?php $__empty_2 = true; $__currentLoopData = $r->items; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $item): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_2 = false; ?><div class="d-flex justify-content-between mt-2"><span><?php echo e($item->menu->nama); ?> × <?php echo e($item->jumlah); ?></span><span>Rp<?php echo e(number_format($item->harga_satuan*$item->jumlah,0,',','.')); ?></span></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_2): ?><p class="subtitle">Tidak ada item.</p><?php endif; ?></div><div class="col-md-5 mt-3 mt-md-0"><div class="d-flex justify-content-between"><span>Total menu</span><strong>Rp<?php echo e(number_format($r->total_harga,0,',','.')); ?></strong></div><div class="d-flex justify-content-between mt-2"><span>DP</span><strong>Rp<?php echo e(number_format($r->dp_nominal,0,',','.')); ?></strong></div><div class="d-flex justify-content-between mt-2"><span>Sisa bayar</span><strong>Rp<?php echo e(number_format(max(0,$r->total_harga-($r->status_pembayaran==='lunas'?$r->total_harga:$r->dp_nominal)),0,',','.')); ?></strong></div><?php if($r->alasan_penolakan): ?><p class="text-danger small mt-2">Alasan penolakan: <?php echo e($r->alasan_penolakan); ?></p><?php endif; ?></div></div></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="panel text-center py-5"><h5>Belum ada reservasi</h5><p class="subtitle">Cari restoran dan pesan meja untuk mulai.</p><a class="btn btn-purple" href="<?php echo e(route('customer.index')); ?>">Cari resto</a></div><?php endif; ?></div><?php $__env->stopSection(); ?>

